Interpreters vs Compilers:
// Interpreter: executes AST directly
function interpret(code) {
    const ast = parse(code);
    return evaluate(ast);
}

// Compiler: translates first
function compileAndRun(source) {
    const binary = compile(source);
    binary.run();
}

