Error Recovery:
// Panic mode: skip to sync token
const SYNCH_TOKENS = new Set([';', '}', '{']);
function recover() {
    while (pos < tokens.length) {
        if (SYNCH_TOKENS.has(tokens[pos].value)) return;
        pos++;
    }
}

Type Checking:
class TypeChecker {
    check(node) {
        if (node.type === 'NumberExpr') return 'number';
        if (node.type === 'BinaryExpr') {
            const l = this.check(node.left);
            const r = this.check(node.right);
            if (l !== r) throw new TypeError('Type mismatch');
            return l;
        }
    }
}

Symbol Tables:
class Scope {
    constructor(parent) {
        this.symbols = new Map();
        this.parent = parent;
    }
    lookup(name) {
        if (this.symbols.has(name)) return this.symbols.get(name);
        if (this.parent) return this.parent.lookup(name);
        throw new Error('Undefined: ' + name);
    }
}

